"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'The a moonstone Quest', 'author': 'Signature original', 'genre': 'Woodland Friends', 'chapters': [{'n': 1, 'title': 'The Finding', 'text': "a tiny dragon appeared as if called — perhaps by the glow, perhaps by fate. 'That's a moonstone,' a tiny dragon said, eyes wide. 'The stories say it chooses someone. It seems it chose you.'\n\n'We have to fix this,' Wren said. a tiny dragon nodded, brave and small. 'The stories say a moonstone can. The stories also say it's dangerous.' Wren grinned. 'The best things are.'\n\nThat night the Thorn Witch's shadow fell over the Hollow Hill: the brook ran backwards, the mushrooms glowed red, the stars went out one by one. Wren held a moonstone tight. It pulsed, warm as a heartbeat."}, {'n': 2, 'title': 'The Journey', 'text': "At the edge of the Hollow Hill, they looked back at the darkened woods and forward at the Thorn Witch's thorn castle. 'Together?' Wren asked. 'Always,' said a tiny dragon. And in they went.\n\nThey escaped by dewdrop-light, laughing and shaking. a moonstone glowed brighter, as if proud. Wren was starting to understand: it wasn't just a magical object. It was a friend, too.\n\nThe path through the Hollow Hill was a storybook: a brook that sang, mushrooms that lit the way, an oak that bowed. a tiny dragon knew every tale and told them walking, which made the miles shorter and the dark less dark."}, {'n': 3, 'title': 'The Thorn Castle', 'text': "the Thorn Witch's jar cracked. A single star escaped — then another, then a flood of starlight, pouring back to the Hollow Hill. the Thorn Witch shrank with every star, smaller, smaller, till only a grumble remained. The Grumble King, indeed.\n\nthe Thorn Witch's castle was made of thorns and sulks. The door asked for a password. a tiny dragon guessed 'please' — and it worked, because manners are magic the Thorn Witch never learned.\n\nWren held up a moonstone. 'Not this,' Wren said. 'This chose me.' the Thorn Witch laughed — a sound like dead leaves — and sent the shadow crows. a tiny dragon met them with the owl's feather and total fearlessness."}, {'n': 4, 'title': 'Starlight Restored', 'text': "They carried the starlight home to the Hollow Hill in a moonstone, which had grown to hold it all. The brook ran forward again. The mushrooms glowed gold. The stars came back, one by one, like friends returning.\n\nthe Hollow Hill celebrated: the fireflies spelled Wren's name, the oak dropped acorns of thanks, the wise owl composed a ballad with a tiny dragon as the hero — a tiny dragon insisted Wren was the hero; they compromised on both.\n\na moonstone chose to stay with Wren — or Wren chose to stay with it; by now they weren't sure there was a difference. It sits by the bed, glowing softly, a nightlight of pure story."}, {'n': 5, 'title': 'The Promise Kept', 'text': "a tiny dragon is older now, greyer, no less brave. They still walk together, still argue about the ballad, still keep the grumble-jar dusted. Friendship, like starlight, doesn't fade if you tend it.\n\nbe brave, be kind. In the Hollow Hill, in the starlight, in every heart that hears the tale: the promise kept, the story told, the magic real.\n\nWren grew, as heroes do, but never grew out of the Hollow Hill. Every spring they check the old oak. Every night a moonstone glows. Every tale a tiny dragon tells starts, 'When we saved the stars...'"}, {'n': 6, 'title': 'Bedtime', 'text': "Wren smiles from the doorway. Outside, the stars are out — all of them, every one, back where they belong. The brook sings. The fireflies dance.\n\nbe brave, be kind. Goodnight.\n\n'Again,' says the listener. It is always 'again.' The best stories are."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

